}

/// Applies a single operation to an account, returning the new account state.
fn apply(in acc: Account, in op: Op) -> Account {
    match op {
        Op::Deposit { amount } => {
            Account { balance: acc.balance + amount }
        }
        Op::Withdraw { amount } => {
            if acc.balance >= amount {
                Account { balance: acc.balance - amount }
            } else {
                acc // Insufficient funds, return unchanged account
            }
        }
    }
}

