module list_ops;

struct Node {
    value: Int,
    next: Option[Box[Node]]
}

/// Builds a singly linked list: a -> b -> c
fn list3(take a: Int, take b: Int, take c: Int) -> Node {
    // Create the last node (c)
    let node_c = Node { value: c, next: None };

    // Create the middle node (b) pointing to c
    let node_b = Node { value: b, next: Some { value: node_c, next: None } };

    // Create the first node (a) pointing to b
    Node { value: a, next: Some { value: node_b, next: None } }
}

/// Returns the sum of every value in the list.
fn sum_list(in n: Node) -> Int {
    let mut current = n;
    let mut sum = 0;

    // Use a loop structure to traverse the Option[Box[Node]] chain
    // We must manually unwrap/reassign to traverse, as 'in' borrows.
    // Since we are consuming the list structure to calculate the sum,
    // we can use a recursive helper or pattern matching on the Option.

    // Recursive helper function to sum the rest of the list
    fn sum_recursive(in node: Node) -> Int {
        let current_sum = node.value;
        match node.next {
            Some { value: next_node, next: _ } => {
                // We must consume the Box to recurse, so we take ownership of the next node
                let next_node_owned = std::boxed::get(next_node);
                current_sum + sum_recursive(next_node_owned)
            }
            None => current_sum
        }
    }

    // Since the input 'n' is taken by value (consumed), we can pass it to the recursive helper.
    sum_recursive(current)
}

/// Returns the number of nodes in the list.
fn length(in n: Node) -> Int {
    let mut count = 0;
    let mut current = n;

    // Similar to sum_list, we consume the list structure to count nodes.
    fn count_recursive(in node: Node) -> Int {
        let count = 1;
        match node.next {
            Some { value: next_node, next: _ } => {
                let next_node_owned = std::boxed::get(next_node);
                count + count_recursive(next_node_owned)
            }
            None => count
        }
    }

    count_recursive(current)
}

