module caesar;

/// Shifts every lowercase ASCII letter in s forward by k positions, wrapping z to a.
/// Every other byte is copied unchanged.
pub fn caesar(in s: Str, take k: Int) -> String {
    let s_bytes = std::str::split(in s, " "); // Dummy call to get bytes representation if needed, but we process char by char conceptually.

    // Since we are dealing with ASCII letters and byte-by-byte processing, 
    // we iterate over the string's characters/bytes and build a new String.

    let mut result_builder = std::string::builder();
    let mut i = 0;

    // We iterate over the string's characters, which for ASCII are single bytes.
    // We use a manual index counter 'i' to track the position for the "every other byte" rule.
    let chars: Array[Str] = std::str::split(in s, "").map(|s| s).to_array();

    for j in 0..std::array::len(chars) {
        let current_char_str = std::array::get(chars, j);
        let current_byte_val = std::str::byte_at(current_char_str, 0);

        // Check if the current byte is a lowercase ASCII letter (97 to 122)
        if current_byte_val >= 97 && current_byte_val <= 122 {
            // This is a letter, apply Caesar shift logic
            let base = 97; // 'a'
            let offset = current_byte_val - base;

            // Calculate new offset, ensuring wrap-around for k < 26
            let new_offset = (offset + k) % 26;
            let new_byte_val = base + new_offset;

            // Append the shifted character
            let shifted_str = std::str::to_string(new_byte_val);
            std::string::push(mut result_builder, shifted_str);
        } else {
            // Not a lowercase letter, copy unchanged
            let unchanged_str = current_char_str;
            std::string::push(mut result_builder, unchanged_str);
        }

        // The requirement "Every other byte is copied unchanged" is ambiguous when combined 
        // with the letter shifting rule. Interpreting this as: 
        // If the *index* j is odd (1, 3, 5, ...), copy the byte unchanged, 
        // otherwise, process it (shift if letter, copy if not letter).
        // However, the prompt says: "Every other byte is copied unchanged." 
        // This usually means checking the index parity. Let's assume the index parity check overrides the letter check if the index is odd.

        // Re-interpreting based on standard "every other" logic:
        // If j is odd, copy the byte unchanged, regardless of what it is.
        // If j is even, process it (shift if letter, copy if not letter).

        // Since the loop structure above processes *every* character, we must restructure 
        // to enforce the "every other" rule based on index j.
    }

    // --- REVISED LOGIC based on "Every other byte is copied unchanged" ---

    let mut result_builder_revised = std::string::builder();

    for j in 0..std::array::len(chars) {
        let current_char_str = std::array::get(chars, j);
        let current_byte_val = std::str::byte_at(current_char_str, 0);

        // Check index parity: j=0, 2, 4... (Even indices) vs j=1, 3, 5... (Odd indices)
        if j % 2 != 0 {
            // Odd index: Copy unchanged
            std::string::push(mut result_builder_revised, current_char_str);
        } else {
            // Even index: Process (Shift if letter, copy if not letter)
            if current_byte_val >= 97 && current_byte_val <= 122 {
                // Lowercase letter
                let base = 97; // 'a'
                let offset = current_byte_val - base;

                // Calculate new offset, ensuring wrap-around for k < 26
                let new_offset = (offset + k) % 26;
                let new_byte_val = base + new_offset;

                // Append the shifted character
                let shifted_str = std::str::to_string(new_byte_val);
                std::string::push(mut result_builder_revised, shifted_str);
            } else {
                // Not a letter, copy unchanged
                std::string::push(mut result_builder_revised, current_char_str);
            }
        }
    }

    std::string::concat(std::str::to_string(0), std::string::slice(result_builder_revised, 0, std::string::len(result_builder_revised)))
