/// Computes the n-th Fibonacci number iteratively.
pub fn fib(take n: Int) -> Int {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }

    var a = 0; // F(i-2)
    var b = 1; // F(i-1)
    var result = 0;

    // We start the loop from i=2 up to n
    var i = 2;
    while i <= n {
        // F(i) = F(i-1) + F(i-2)
        result = a + b;

        // Shift for next iteration:
        // New F(i-2) becomes old F(i-1)
        a = b;
        // New F(i-1) becomes F(i)
        b = result;

        i = i + 1;
    }
    result
}

