import std::collections;
import std::array;

/// Counts the occurrences of a specific value v in the array xs.
pub fn count_of(in xs: [Int; 8], take v: Int) -> Int {
    // 1. Build a frequency map: Map[Int, Int]
    var counts: std::map::Map[Int, Int] = std::map::empty();
    for x in xs {
        // Use std::map::insert to increment the count.
        // If the key exists, insert returns Some(old_value).
        // We use the result of insert to calculate the new value.
        let current_count = std::map::get(counts, x).unwrap_or(0);
        std::map::insert(counts, x, current_count + 1);
    }

    // 2. Look up v in the map, returning 0 if not found.
    match std::map::get(counts, v) {
        Some { value } => value,
        None => 0,
    }
}

/// Counts the number of distinct values in the array xs.
pub fn distinct(in xs: [Int; 8]) -> Int {
    // 1. Build a frequency map: Map[Int, Int]
    var counts: std::map::Map[Int, Int] = std::map::empty();
    for x in xs {
        // Since we only care about presence, we just insert/update.
        // The value stored doesn't matter, but we must provide one.
        // We use 1 as a placeholder value.
        std::map::insert(counts, x, 1);
    }

    // 2. The number of distinct elements is the size of the map.
    std::map::len(counts)
}

