    // We can use std::core::max(1, n) as the upper bound for the search range [low, high].

    var low: Int = 0;
    // Set high to n+1, but clamp it to prevent overflow if n is I64::MAX.
    // Since we are looking for r*r <= n, r <= n. If n is large, r is much smaller.
    // The largest possible square root for an I64 is around 3,037,000,499.
    // We can use a fixed safe upper bound, or just n if n is small.
    // Let's use std::core::min(n, 3037000500) as a practical upper bound,
    // but sticking to the binary search structure:
    var high: Int = n + 1;
    if high < 0 { // Overflow check for n=I64::MAX
        high = 3037000500; // A safe upper bound for I64 square root
    }

    var result: Int = 0;

    while low < high {
        // Calculate mid = low + (high - low) / 2 to prevent overflow
        var mid: Int = low + (high - low) / 2;

        // Check for potential overflow when calculating mid * mid
        // Since mid is at most n, and n is Int, mid*mid might overflow.
        // We must check if mid > n / mid (for mid > 0) or if mid is too large.
        var square: Int;
        if mid == 0 {
