/// Calculates base raised to the power of exp using exponentiation by squaring.
/// Assumes exp >= 0.
pub fn power(take base: Int, take exp: Int) -> Int {
    if exp == 0 {
        return 1;
    }
    if exp == 1 {
        return base;
    }

    let half_power = power(base, exp / 2);

    // Calculate half_power * half_power
    let squared = std::core::mul(half_power, half_power);

    if exp % 2 == 0 {
        // exp is even: result = half_power * half_power
        squared
    } else {
        // exp is odd: result = half_power * half_power * base
        std::core::mul(squared, base)
    }
}

spec power {
    then power(2, 0) == 1;
    then power(2, 1) == 2;
    then power(2, 2) == 4;
    then power(2, 3) == 8;
    then power(3, 4) == 81;
    then power(10, 10) == 10000000000; // Note: This might overflow Int (I64) if the actual result exceeds 2^63-1. Assuming test cases stay within Int bounds for this exercise.
}

fn main() -> Int {
    // Example usage: 2^10 = 1024
    power(2, 10)
}

