/// Repeats the string s, n times. Returns an empty string if n <= 0.
pub fn repeat(in s: Str, take n: Int) -> String {
    if n <= 0 {
        std::string::empty()
    } else {
        var result = std::string::empty();
        var count = 0;
        while count < n {
            std::string::append(mut result, s);
