module rle_encoder;

import std::str;
import std::array;

/// Returns the run-length encoding of the input string.
/// Each maximal run of one repeated byte becomes that byte followed by the run's length in decimal.
/// "aaabcc" becomes "a3b1c2". The empty string encodes to the empty string.
pub fn rle(in s: Str) -> String {
    if std::str::len(in s) == 0 {
        std::string::empty()
    } else {
        var result_builder = std::string::builder();
        let bytes = std::str::slice(in s, 0, std::str::len(in s));

        let mut i = 0;
        let total_len = std::str::len(in s);

        while i < total_len {
            let current_byte = std::str::byte_at(in s, i);
            let mut count = 1;
            let mut j = i + 1;

            while j < total_len && std::str::byte_at(in s, j) == current_byte {
                count = count + 1;
                j = j + 1;
            }

            // Append the byte
            result_builder = std::string::push(result_builder, std::str::to_string(current_byte));

            // Append the count as a string
            result_builder = std::string::push(result_builder, std::str::to_string(count));

            // Move index i to the start of the next run
            i = j;
        }
        result_builder
    }
}

spec rle {
    then rle(std::str::from_str("")).to_string() == "";
    then rle(std::str::from_str("a")).to_string() == "a1";
    then rle(std::str::from_str("aa")).to_string() == "a2";
    then rle(std::str::from_str("aaa")).to_string() == "a3";
    then rle(std::str::from_str("aaabcc")).to_string() == "a3b1c2";
    then rle(std::str::from_str("aabbccddeeff")).to_string() == "a2b2c2d2e2f2";
    then rle(std::str::from_str("abc")).to_string() == "a1b1c1";
    then rle(std::str::from_str("zyxw")).to_string() == "z1y1x1w1";
}

fn main() -> Int {
    // Example usage, main returns 0 on success
    let test_str = std::str::from_str("mississippi");
    let encoded = rle(test_str);
    std::io::println(std::str::from_str("Input: mississippi, Encoded: " + encoded)).unwrap();
    0
}

