module rle_encoder;

import std::str;
import std::string;
import std::array;

/// Returns the run-length encoding of the input string.
/// Each maximal run of one repeated byte becomes that byte followed by the run's length in decimal.
/// "aaabcc" becomes "a3b1c2". The empty string encodes to the empty string.
pub fn rle(s: Str) -> String {
    if std::str::len(s) == 0 {
        std::string::empty()
    } else {
        var result_builder = std::string::builder();

        let total_len = std::str::len(s);
        var i = 0;

        while i < total_len {
            let current_byte = std::str::byte_at(s, i);
            var count = 1;
            var j = i + 1;

            while j < total_len && std::str::byte_at(s, j) == current_byte {
                count = count + 1;
                j = j + 1;
            }

            // Append the byte (as a single character string)
            result_builder = std::string::push(result_builder, std::str::from_str(std::str::to_string(current_byte)));

            // Append the count as a string
            result_builder = std::string::push(result_builder, std::str::to_string(count));

            // Move index i to the start of the next run
            i = j;
        }
        result_builder
    }
}

spec rle {
    then rle(std::str::from_str("")) == "";
    then rle(std::str::from_str("a")) == "a1";
    then rle(std::str::from_str("aa")) == "a2";
    then rle(std::str::from_str("aaa")) == "a3";
    then rle(std::str::from_str("aaabcc")) == "a3b1c2";
    then rle(std::str::from_str("aabbccddeeff")) == "a2b2c2d2e2f2";
    then rle(std::str::from_str("abc")) == "a1b1c1";
    then rle(std::str::from_str("zyxw")) == "z1y1x1w1";
}

