pub fn to_binary(take n: Int) -> String {
    if n < 0 {
        // Based on the prompt, we assume n >= 0, but handle defensively.
        return "Error: Negative input".to_string();
    }
    if n == 0 {
        return "0".to_string();
    }

    let mut result_builder = std::string::builder();
    let mut current_n = n;

    while current_n > 0 {
        // Get the least significant bit (remainder when divided by 2)
        let bit = current_n % 2;

        // Prepend the bit to the result string (since we process LSB to MSB)
        // We use push_int and then rely on the fact that we are building the string
        // in reverse order of calculation, so we must prepend or reverse later.
        // Since we are building it iteratively, let's build it in reverse order
        // and then reverse the final string.

        // A simpler approach is to build an array of characters/strings and join,
        // but sticking to String building:

        // Append the bit (as a character '0' or '1')
        if bit == 1 {
            result_builder.push_byte(1); // Pushing the byte value 1
        } else {
            result_builder.push_byte(0); // Pushing the byte value 0
        }

        // Shift right (integer division by 2)
        current_n = current_n / 2;
    }

    // The string is currently LSB first. We need to reverse it.
    let raw_string = result_builder.as_str();

    // Since we pushed bytes, we need to convert the byte sequence back to a string
    // and then reverse it.
    let bytes_array = std::array::filled(std::string::len(raw_string), 0); // Placeholder, need actual byte array

    // Re-implementing the string building to be cleaner:
    let mut bits: Array[Str] = std::array::empty();
    let mut temp_n = n;
    while temp_n > 0 {
        let bit = temp_n % 2;
        let bit_str = if bit == 1 { "1".to_string() } else { "0".to_string() };
        bits = std::array::push(bits, bit_str);
        temp_n = temp_n / 2;
    }

    // The array 'bits' is now [LSB, ..., MSB]. We need to reverse it.
    let reversed_bits = std::collections::sorted_descending(bits);

    // Join the parts.
    std::string::join(reversed_bits, "")
}

