module word_utils;

import std::str;
import std::array;
import std::map;

/// Returns the length of the longest space-separated word in text.
/// Returns 0 for text with no words.
pub fn longest_word_length(in text: Str) -> Int {
    let parts: Array[String] = std::str::split(in text, " ");

    var max_len: Int = 0;

    for word_str in parts {
        // Filter out empty strings that might result from multiple spaces
        if !word_str.is_empty() {
            let len = std::string::len(word_str);
            if len > max_len {
                max_len = len;
            }
        }
    }
    max_len
}

/// Counts how many space-separated words in text equal word exactly.
/// Uses a Map[Str, Int] internally.
pub fn count_word(in text: Str, in word: Str) -> Int {
    // 1. Split the text into all words
    let parts: Array[String] = std::str::split(in text, " ");

    // 2. Build a frequency map of all words
    let mut word_counts: std::map::Map[Str, Int] = std::map::empty();

    for word_str in parts {
        // Only count non-empty strings as words
        if !word_str.is_empty() {
            // std::map::insert returns Option[V], we only care about the side effect of insertion/update
            std::map::insert(word_counts, word_str, 1);
        }
    }

    // 3. Look up the count for the target word
    match std::map::get(word_counts, word) {
        Some { value } => value,
        None => 0,
    }
}

