module word_utils;

import std::str;
import std::array;
import std::map;

/// Returns the length of the longest space-separated word in text.
/// Returns 0 for text with no words.
pub fn longest_word_length(in text: Str) -> Int {
    // std::str::split returns Array[String]
    let parts: Array[String] = std::str::split(in text, " ");

    var max_len: Int = 0;

    for word_str in parts {
        // Check if the string is empty using std::str::contains_byte or similar logic,
        // but since we are splitting by " ", we must handle multiple spaces resulting in empty strings.
        // The most robust way to check for emptiness is to compare length to 0.
        if std::string::len(word_str) > 0 {
            let len = std::string::len(word_str);
            if len > max_len {
                max_len = len;
            }
        }
    }
    max_len
}

/// Counts how many space-separated words in text equal word exactly.
/// Uses a Map[Str, Int] internally.
pub fn count_word(in text: Str, in word: Str) -> Int {
    // 1. Split the text into all words
    let parts: Array[String] = std::str::split(in text, " ");

    // 2. Build a frequency map of all words
    var word_counts: std::map::Map[Str, Int] = std::map::empty();

    for word_str in parts {
        // Only count non-empty strings as words
        if std::string::len(word_str) > 0 {
            // We must use std::map::insert to update the count, but std::map::insert
            // only returns Option[V] and doesn't support incrementing easily.
            // We must use get/update logic or rely on the fact that we only need the final count.

            // Since we are building a frequency map, we must simulate incrementing.
            // We will use a temporary map to count frequencies first, then look up.
            // However, the requirement is to use Map[Str, Int] and count occurrences.

            // Let's stick to the required structure: build map, then count.
            // Since we cannot increment easily, we will build a map of unique words,
            // and then iterate over the parts again to count matches.
            // But the prompt implies the map should hold the counts.

            // Workaround: Use a temporary map to store counts, simulating the required behavior.
            // If the word exists, we must retrieve it, increment it, and put it back.

            let current_count = std::map::get(word_counts, word_str).unwrap_or(0);
            word_counts = std::map::insert(word_counts, word_str, current_count + 1);
        }
    }

    // 3. Look up the count for the target word
    match std::map::get(word_counts, word) {
        Some { value } => value,
        None => 0,
    }
}

